import random
from collections import Counter

def check_sort(fn, trials=300):
    rng = random.Random(7)
    for t in range(trials):
        xs = [rng.randint(-20, 20) for _ in range(rng.randint(0, 12))]
        out = fn(xs)
        if any(out[i] > out[i + 1] for i in range(len(out) - 1)):
            return f"trial {t}: output not ordered: {xs} -> {out}"
        if Counter(out) != Counter(xs):
            return f"trial {t}: elements changed: {xs} -> {out}"
        if fn(out) != out:
            return f"trial {t}: not idempotent: {out} -> {fn(out)}"
    return f"all {trials} trials passed"

print(check_sort(sorted))
def broken_sort(xs):   # drops duplicates
    return sorted(set(xs))
print(check_sort(broken_sort))

