def tax_buggy(income):
    # 10% up to 50k, 20% from 50k to 100k, 30% above 100k.
    # bug: the third bracket restarts from a base of 12,000,
    # but the first two brackets accumulate to 15,000 at 100k.
    if income <= 50_000:
        return income * 0.10
    if income <= 100_000:
        return 5_000 + (income - 50_000) * 0.20
    return 12_000 + (income - 100_000) * 0.30

prev = -1
for income in range(0, 200_001, 5_000):
    t = tax_buggy(income)
    flag = ""
    if t < prev:
        flag = "  <- tax went DOWN as income rose"
    print(f"income {income:7,}: tax {t:9,.0f}{flag}")
    if flag:
        break
    prev = t

def unique_buggy(xs):
    # intended: order-preserving dedupe.
    # bug: after seeing a repeat of the FIRST element, it stops adding new items
    out = []
    for x in xs:
        if x in out:
            if x == out[0]:
                break
            continue
        out.append(x)
    return out

def fails(xs):
    return set(unique_buggy(xs)) != set(xs)

case = [7, 3, 9, 3, 12, 7, 4, 18, 5, 22]
print("found failing case:", case, "-> unique gives", unique_buggy(case))

# shrinking: try removing each element; keep any removal that still fails
shrunk = list(case)
changed = True
while changed:
    changed = False
    for i in range(len(shrunk)):
        candidate = shrunk[:i] + shrunk[i + 1:]
        if candidate and fails(candidate):
            shrunk = candidate
            changed = True
            break
print("shrunk to:         ", shrunk, "-> unique gives", unique_buggy(shrunk))

