class FakeGateway:
    def __init__(self, script):
        self.script = list(script)   # outcomes to play back, in order
        self.charges = []
    def charge(self, amount):
        outcome = self.script.pop(0)
        if outcome == "success":
            self.charges.append(amount)
            return {"status": "paid", "id": f"ch_{len(self.charges)}"}
        if outcome == "declined":
            return {"status": "declined", "reason": "insufficient funds"}
        return {"status": "timeout"}   # no answer: the charge may or may not exist

def checkout(amount, gateway):
    result = gateway.charge(amount)
    if result["status"] == "paid":
        return f"order confirmed ({result['id']})"
    if result["status"] == "declined":
        return f"payment declined: {result['reason']} - ask for another card"
    return "payment unknown: do NOT retry blindly; reconcile first"

for scenario in ["success", "declined", "timeout"]:
    gw = FakeGateway([scenario])
    print(f"{scenario:9s} -> {checkout(120, gw)}")

class InMemoryUsers:
    def __init__(self):
        self.rows = {}
        self.next_id = 1
    def save(self, name, email):
        if any(r["email"] == email.lower() for r in self.rows.values()):
            raise ValueError("duplicate email")
        uid = self.next_id
        self.next_id += 1
        self.rows[uid] = {"id": uid, "name": name, "email": email.lower()}
        return uid
    def get(self, uid):
        return self.rows.get(uid)
    def find_by_email(self, email):
        for r in self.rows.values():
            if r["email"] == email.lower():
                return r
        return None

