    log = [f"day {clock.day}: initial charge -> {gateway.charge()}"]
    for wait in (1, 3, 7):
        clock.advance(wait)
        outcome = gateway.charge()
        log.append(f"day {clock.day}: retry after {wait}d -> {outcome}")
