from collections import deque

class ListQueue:
    def __init__(self):  self.items = []
    def push(self, x):   self.items.append(x)
    def pop(self):       return self.items.pop(0)
    def __len__(self):   return len(self.items)

class DequeQueue:
    def __init__(self):  self.items = deque()
    def push(self, x):   self.items.append(x)
    def pop(self):       return self.items.popleft()
    def __len__(self):   return len(self.items)

def contract(q):
    q.push("first"); q.push("second"); q.push("third")
    return [q.pop(), q.pop(), len(q), q.pop()]

for name, q in [("list-backed ", ListQueue()), ("deque-backed", DequeQueue())]:
    print(name, "->", contract(q))
